class Enemy {
public:
  Enemy(const EnemyType& type) : type_(type), hp_(type.maxHp()) {}
  void update(float dt) { pathT_ += type_.speed() * dt; }
private:
  const EnemyType& type_;
  int hp_;          // instance state
  float pathT_ = 0; // instance state
};

// Loaded from enemies.json (may come from a hot update)
