using AiFn = void (*)(Monster&, World&);

void aiStandStill(Monster&, World&) {}
void aiChase(Monster& m, World& w) { m.moveToward(w.hero().pos()); }
void aiFlee(Monster& m, World& w) { m.moveAwayFrom(w.hero().pos()); }

std::map<std::string, AiFn> aiTable = {
  {"stand", aiStandStill}, {"chase", aiChase}, {"flee", aiFlee}
};

class Breed {
public:
  AiFn ai() const { return ai_; }  // like a vtable slot
private:
  AiFn ai_;
  int health_;
};

void Monster::update(World& world) { breed_.ai()(*this, world); }

// Copy-down delegation: resolve inheritance once, at load time
MonsterType::MonsterType(const MonsterType* parent, int armor, const char* name)
  : armor_(armor), name_(name) {
  if (parent != nullptr) {
    if (armor == 0) armor_ = parent->armor();
  }
}
int MonsterType::armor() const { return armor_; }

// Dynamic delegation (editor build): walk the chain on every lookup
int EditorMonsterType::armor() const {
  if (armor_ != 0 || parent_ == nullptr) return armor_;
  return parent_->armor();
}

void Monster::setBreed(Breed& newBreed) {
  log("breed change: %s -> %s", breed_->name(), newBreed.name());
  breed_ = &newBreed;
  // Re-establish the invariants the new type relies on
  if (health_ > newBreed.getHealth()) health_ = newBreed.getHealth();
  skills_.removeIf([&](const Skill& s) { return !newBreed.allows(s); });
  ai_.reset();
}
